#!/bin/bash
# GRPO on GSM8K with score function centering (SFC) in separate-async training: the
# rollout GPUs keep generating while the trainer updates, so training data is
# generated by older weights. The generator can run up to 8 batches ahead, and each
# 64-prompt batch is split into 16 optimizer steps. In a reference run with Qwen3-0.6B
# (rollout_concurrency 192 and tps_limit 8 in agentcore_agent.yaml), tokens were
# about 90 optimizer steps old when trained on: plain REINFORCE collapsed, and SFC
# reached 0.74 GSM8K validation reward.
#
# SFC replaces verl's policy loss (see ../../score_centering.py) and is configured
# by the score_centering.* overrides below: K draws per generated token and β₀ of
# the age-decayed KL. The trainer checks the required verl settings at startup.
#
# Prerequisites (in addition to those of fsdp_fft_sync_grpo.sh):
#   1. uv sync --extra verl   (re-run after pulling, so vLLM registers the
#      vllm_token_samples plugin)
#   2. uv pip install cupy-cuda13x   (verl's NCCL weight sync for separate-async)
#
# GPUs: TRAINER_GPUS for FSDP training plus ROLLOUT_GPUS for standalone vLLM, on
# one node. The defaults (2 + 2) match the reference run.
set -x

export HYDRA_FULL_ERROR=1
export VERL_USE_EXTERNAL_MODULES=agentcore_rl_toolkit.backends.verl.trainer
export AGENTCORE_VLLM_TOKEN_SAMPLES=1  # vLLM draws the samples (read by vLLM's processes)

SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
AGENT_LOOP_CONFIG=$SCRIPT_DIR/agentcore_agent.yaml

gsm8k_train_path=gsm8k/gsm8k_agent_train.parquet
gsm8k_test_path=gsm8k/gsm8k_agent_test.parquet
train_files="['$gsm8k_train_path']"
test_files="['$gsm8k_test_path']"

PROJECT_NAME=${PROJECT_NAME:-agentcore_grpo}
EXPERIMENT_NAME=${EXPERIMENT_NAME:-gsm8k_qwen3_0.6b_separate_async_sfc}
CKPTS_DIR=${CKPTS_DIR:-checkpoints/${PROJECT_NAME}/${EXPERIMENT_NAME}}
MAX_MODEL_LEN=${MAX_MODEL_LEN:-16384}
TRAINER_GPUS=${TRAINER_GPUS:-2}
ROLLOUT_GPUS=${ROLLOUT_GPUS:-2}

python3 -m verl.trainer.main_ppo \
    +score_centering.num_auxiliary_token_samples=8 \
    +score_centering.kl_beta=0.3 \
    trainer.v1.trainer_mode=agentcore_separate_async \
    trainer.v1.separate_async.parameter_sync_step=16 \
    trainer.v1.separate_async.num_warmup_batches=8 \
    trainer.v1.sampler.max_off_policy_threshold=24 \
    algorithm.adv_estimator=grpo \
    algorithm.norm_adv_by_std_in_grpo=true \
    algorithm.use_kl_in_reward=False \
    algorithm.rollout_correction.rollout_is=null \
    algorithm.rollout_correction.bypass_mode=true \
    data.train_files="$train_files" \
    data.val_files="$test_files" \
    data.train_batch_size=64 \
    data.val_batch_size=256 \
    data.max_prompt_length=14336 \
    data.max_response_length=$MAX_MODEL_LEN \
    data.custom_cls.path=pkg://agentcore_rl_toolkit.backends.verl.dataset \
    data.custom_cls.name=PayloadDataset \
    actor_rollout_ref.model.path=Qwen/Qwen3-0.6B \
    actor_rollout_ref.model.use_remove_padding=True \
    actor_rollout_ref.actor.optim.lr=1e-6 \
    actor_rollout_ref.actor.ppo_mini_batch_size=4 \
    actor_rollout_ref.actor.use_dynamic_bsz=True \
    actor_rollout_ref.actor.ppo_max_token_len_per_gpu=$MAX_MODEL_LEN \
    actor_rollout_ref.actor.use_kl_loss=False \
    actor_rollout_ref.actor.entropy_coeff=0 \
    actor_rollout_ref.actor.calculate_entropy=True \
    actor_rollout_ref.actor.loss_agg_mode=seq-mean-token-sum \
    actor_rollout_ref.rollout.name=vllm \
    actor_rollout_ref.rollout.mode=async \
    actor_rollout_ref.rollout.calculate_log_probs=true \
    actor_rollout_ref.rollout.prompt_length=14336 \
    actor_rollout_ref.rollout.response_length=$MAX_MODEL_LEN \
    actor_rollout_ref.rollout.max_model_len=$MAX_MODEL_LEN \
    actor_rollout_ref.rollout.enforce_eager=False \
    actor_rollout_ref.rollout.temperature=1.0 \
    actor_rollout_ref.rollout.tensor_model_parallel_size=1 \
    actor_rollout_ref.rollout.gpu_memory_utilization=0.5 \
    actor_rollout_ref.rollout.n=4 \
    actor_rollout_ref.rollout.nnodes=1 \
    actor_rollout_ref.rollout.n_gpus_per_node=$ROLLOUT_GPUS \
    actor_rollout_ref.rollout.checkpoint_engine.backend=nccl \
    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=1 \
    actor_rollout_ref.rollout.val_kwargs.n=1 \
    actor_rollout_ref.rollout.val_kwargs.temperature=0.6 \
    actor_rollout_ref.rollout.val_kwargs.do_sample=True \
    actor_rollout_ref.rollout.agent.num_workers=1 \
    actor_rollout_ref.rollout.agent.default_agent_loop=agentcore_agent \
    actor_rollout_ref.rollout.agent.agent_loop_config_path="$AGENT_LOOP_CONFIG" \
    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=1 \
    trainer.critic_warmup=0 \
    trainer.default_local_dir="$CKPTS_DIR" \
    trainer.resume_mode=disable \
    trainer.logger='["console"]' \
    trainer.project_name="$PROJECT_NAME" \
    trainer.experiment_name="$EXPERIMENT_NAME" \
    trainer.val_before_train=true \
    trainer.n_gpus_per_node=$TRAINER_GPUS \
    trainer.nnodes=1 \
    trainer.save_freq=20 \
    trainer.test_freq=10 \
    trainer.total_epochs=1 "$@"
